/* Prototype operating record, inspired by VHU2026 pp181/186 field order.
   No book artwork is reproduced. Construction authority remains in engine.js. */
(function(root){
'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render({state:s,result:r,F,fmt,money,band,signed,comfortName,equipmentDetail}){
 const status=!r.valid?'INVALID DRAFT':r.review?'REVIEW REQUIRED':'CONSTRUCTION CHECKS PASSED';
 const row=(label,value)=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`;
 const core=[['Autopilot',/^Autopilot \(/],['Communications',/Transceiver|Satellite Uplink/],['Navigation',/^Navigation System/],['Sensors',/^Sensor System/],['Camouflage',/^Camouflage \(/],['Stealth',/^Stealth \(/]];
 const coreDetail=e=>{const o=F.options.find(o=>o.Name===e.name);return [o.Bonus!==null&&o.Bonus!==undefined?'DM '+signed(Number(o.Bonus)+(o.Name.startsWith('Sensor System')&&e.highFidelity?1:0)):'',/^[+-]?\d+(?:\.\d+)?$/.test(equipmentDetail(o,e))&&Number(equipmentDetail(o,e))===Number(o.Bonus)?'':equipmentDetail(o,e)].filter(Boolean).join(', ');};
 const systemRows=core.map(([label,re])=>row(label,s.equipment.filter(e=>re.test(e.name)).map(e=>`${e.name.includes('underwater')?'Underwater: ':''}${coreDetail(e)||e.name}${e.quantity!==1?' × '+fmt(e.quantity):''}`).join('; ')||'—')).join('');
 const gear=[`${s.control} × ${s.controlQuantity||1}`,...s.equipment.map(e=>{
  const detail=core.some(([,re])=>re.test(e.name))?'':equipmentDetail(F.options.find(o=>o.Name===e.name),e);
  return `${e.name} × ${fmt(e.quantity)}${detail?' ('+detail+')':''}`;
 })];
 const crew=`${fmt(s.crew)} crew (${comfortName(s.crewSpace)}); `+r.passengerSeating.filter(g=>g.count).map(g=>`${g.name}: ${fmt(g.count)} (${comfortName(g.space)})`).join('; ');
 const stats=[['TL / Skill',`${s.tl} / ${r.t.Skill}`],['Agility',signed(r.agility)],['Speed (cruise)',`${band(r.speed)} (${band(r.cruise)})`],['Range (cruise)',r.infinite?'Source-dependent endurance':`${fmt(r.range)} km (${fmt(r.cruiseRange)} km)`],['Crew / passengers',`${fmt(s.crew)} / ${fmt(r.passengerCount)}`],['Seating',crew],['Overall comfort',r.comfort===null?'No occupants':`${comfortName(r.comfort)} · ${fmt(r.comfort)} CP/person; equipment ${fmt(r.comfortBonus)} CP`],['Cargo',`${fmt(s.cargo)} Spaces / ${fmt(s.cargo*250)} kg`],['Hull [Structure]',`${fmt(r.hull)} [${fmt(r.structure)}]`],['Shipping / Cost',`${fmt(r.shipping)} tons / ${money(r.total)}`]];
 if(s.type==='Submersible')stats.push(['Safe / crush depth',`${fmt(r.depth)} / ${fmt(r.depth*3)} m`]);
 // VHU pp33/52: auxiliary depth uses unmodified primary-submersible depth,
 // halved unless AFV. Reuse the engine baseline; never alter construction totals.
 const auxiliaryDepth=s.depth>0?r.depth/s.depth*(s.features.includes('AFV')?1:.5):null;
 const weapons=r.weaponResults.map(w=>{const source=F.weapons.find(x=>x.Weapon===w.weapon),fittings=[w.gunShield?'Gun shield '+w.gunShield:'',w.autoloader?'Autoloader':'',w.popup?'Pop-up':'',w.modular?'Modular':'',w.remote?'Remote gunner':''];
  return `<tr><td>${esc(w.facing||'Unspecified')} ${esc(w.mount)}: ${esc(w.weapon)} × ${fmt(w.quantity)}${fittings.some(Boolean)?'<small>'+esc(fittings.filter(Boolean).join(', '))+'</small>':''}</td><td>${fmt(w.range)} km</td><td>${esc(w.damage)}${w.quantity>1?'<small>Linked: +1/die per extra weapon before Destructive multiplier</small>':''}</td><td>${source.Mag===null||source.Mag===undefined?'—':fmt(source.Mag)}<small>${source.MagCost===null||source.MagCost===undefined?'—':money(source.MagCost)}</small></td><td>${esc(w.traits||'—')}</td><td>${esc((w.fireControl||'none')+(F.D.FireControl.find(f=>f['Fire Control System']===(w.fireControl||'none'))?.DM?' ('+signed(F.D.FireControl.find(f=>f['Fire Control System']===w.fireControl).DM)+')':''))}</td></tr>`;
 }).join('');
 const reserves=r.weaponResults.filter(w=>w.ammo).map(w=>`${w.facing||'Unspecified'} ${w.weapon}: ${fmt(w.ammo)} ${w.ammoType||'Standard'} rounds${w.ammoType&&w.ammoType!=='Standard'?' — '+w.ammoEffect:''}`);
 const section=(title,body)=>`<section class="op-section"><h2>${esc(title)}</h2>${body}</section>`;
 return `<article class="vehicle-sheet operating-sheet"><div class="op-heading"><h1>${esc(s.name||'Unnamed vehicle')}</h1><strong>${status}</strong><p>${esc(r.size['Size Name'])} ${esc(s.type)} · ${fmt(s.spaces)} Spaces · ${esc(s.hull)} hull</p></div><p class="op-traits"><b>Features & traits:</b> ${esc([...new Set([...r.traits,...s.features])].join(', ')||'None')}</p><div class="op-upper"><dl class="op-stats">${stats.map(([k,v])=>row(k,v)).join('')}</dl><div class="op-armour"><h2>Armour</h2><p>Vehicle-scale (small arms)</p><dl>${F.faces.map((f,i)=>row(f,`${r.protection[i]} (${r.protection[i]+(r.protection[i]>=r.baseArmour?s.tl:0)})`)).join('')}</dl><p><b>Power:</b> ${esc(s.power)}${s.secondary!=='none'?' + '+esc(s.secondary):''}</p><p><b>Output / load:</b> ${fmt(r.pp)} / ${fmt(r.powerDemand)}</p><p><b>Capacity:</b> ${fmt(r.used)} / ${fmt(r.capacity)} Spaces used</p></div></div>${section('Core systems',`<dl class="op-systems">${systemRows}</dl>`)}${section('Equipment',`<p>${esc(gear.join('; '))}.</p>`)}${section('Weapons',weapons?`<table class="op-weapons"><thead><tr><th>Mount / weapon</th><th>Range</th><th>Base damage</th><th>Magazine / cost per weapon</th><th>Traits</th><th>Fire control</th></tr></thead><tbody>${weapons}</tbody></table>`:'<p>Unarmed</p>')}${reserves.length?section('Reserve ammunition','<p>'+esc(reserves.join('; '))+'</p>'):''}${r.auxResults.length?section('Auxiliary drives','<p>'+esc(r.auxResults.map(a=>`${a.name}: ${band(a.speed)}, agility ${signed(a.agility)}, ${fmt(a.range)} km${a.name==='Submarine Drive'?' (safe/crush depth '+(auxiliaryDepth===null?'verify':fmt(auxiliaryDepth)+' / '+fmt(auxiliaryDepth*3)+' m')+'; hostile environment protection)':''}`).join('; '))+'</p>'):''}${s.description?section('Description',`<p class="design-notes">${esc(s.description)}</p>`):''}${r.notes.length?section('Operational notes','<ul>'+r.notes.map(n=>`<li>${esc(n)}</li>`).join('')+'</ul>'):''}${r.issues.length?section('Outstanding construction checks','<ul>'+r.issues.map(i=>`<li><b>${esc(i.level)} · ${esc(i.code)}:</b> ${esc(i.message)} (p${esc(i.page)})</li>`).join('')+'</ul>'):''}<div class="op-footer">Operating sheet prototype · Vehicle Handbook Update 2026 · Full construction record and JSON design available separately. Long records continue without clipping.</div></article>`;
}
root.VehicleOperatingSheet={render};if(typeof module!=='undefined')module.exports={render};
})(typeof globalThis!=='undefined'?globalThis:this);
